class RingBuffer:
    """Shipped broken: overflows past capacity, wrong order, clear is a no-op."""

    def __init__(self, capacity):
        self._capacity = capacity
        self._items = []

    def append(self, item):  # fix this: never overwrites the oldest item
        self._items.append(item)

    def items(self):  # fix this: returns the newest items first
        return list(reversed(self._items))

    def __len__(self):
        return len(self._items)

    def clear(self):  # fix this: does nothing
        pass
